class Solution:

	def printMinNumberForPattern(ob, S):
		start = 0
		prev = S[0]
		result = ''
		S = S + '#'
		for x in range(1, len(S)):
			if prev == S[x]:
				continue
			elif prev == 'I':
				tmp = x + 1 if S[x] == '#' else x
				start += 1 if start != 0 else 0
				while start < tmp:
					start += 1
					result += str(start)
				prev = S[x]
			else:
				tmp = x + 1
				while start < tmp:
					result += str(tmp)
					tmp -= 1
				start = x
				prev = S[x]
		return result
